# Pure append-purpose adapter. No file I/O or Git mutations at transform time.
import base64
import hashlib

EXPECTED_BEFORE = {'src/CMakeLists.txt': 'e6075b1032798f0d3dabb32cc4a1847615dc57e946fd40b341ded62d722638a1', 'src/init.cpp': '33ad54302888d9d095dd8eccee55d98e595d8b8342eda3ff8387ece1ee6f2d58', 'src/net/full_mempool_reconciliation.cpp': None, 'src/net/full_mempool_reconciliation.h': None, 'src/net/txrelay_index.h': 'b74ec84af970c069b4b9ae6188123f9fb12542eba0f0951c3cb6dc74ecb83db9', 'src/net_processing.cpp': '3c7ab9b670b2b7a00dfe2e57207e77b06860df55354b9d3441eca331ef38a548', 'src/test/CMakeLists.txt': '65f1c7beb8e4e176396bb9a377ee6bb428da25b4f01ecc86abd4ed9b24dfc81d', 'src/test/full_mempool_reconciliation_tests.cpp': None, 'src/test/txrelay_tests.cpp': '75133079b53b65186a89500ce2de0be047df4c54950805bf926d4349d12b90db'}
PAYLOAD = {path: base64.b64decode(value) for path, value in {'src/CMakeLists.txt': '', 'src/init.cpp': '', 'src/net/full_mempool_reconciliation.cpp': '', 'src/net/full_mempool_reconciliation.h': '', 'src/net/txrelay_index.h': '', 'src/net_processing.cpp': '', 'src/test/CMakeLists.txt': '', 'src/test/full_mempool_reconciliation_tests.cpp': '', 'src/test/txrelay_tests.cpp': ''}.items()}
EXPECTED_AFTER = {path: hashlib.sha256(value).hexdigest() for path, value in PAYLOAD.items()}

def transform(files):
    def digest(path):
        value = files.get(path)
        return None if value is None else hashlib.sha256(value).hexdigest()
    if all(digest(path) == expected for path, expected in EXPECTED_AFTER.items()):
        return dict(files)
    for path, expected in EXPECTED_BEFORE.items():
        if digest(path) != expected:
            raise ValueError('fullscope preimage mismatch: ' + path)
    out = dict(files)
    out.update(PAYLOAD)
    return out
